<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Job;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class TalentPoolTest extends TestCase{use RefreshDatabase;public function test_verified_company_can_find_save_and_invite_visible_talent():void{$candidate=User::factory()->create(['account_type'=>'candidate','name'=>'Ana Pérez']);$candidate->candidateProfile()->create(['professional_title'=>'Desarrolladora PHP','province'=>'Santiago','skills'=>['PHP'],'talent_visibility'=>'verified_companies','available_for_opportunities'=>true]);$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active','verification_status'=>'verified']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'slug'=>'php','title'=>'PHP','summary'=>'PHP','location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active']);$this->actingAs($owner,'sanctum')->getJson('/api/v1/company/talents?q=PHP')->assertOk()->assertJsonPath('data.data.0.display_name','Ana P.');$this->actingAs($owner,'sanctum')->postJson("/api/v1/company/talents/{$candidate->id}/save",['tags'=>['PHP']])->assertOk();$invitation=$this->actingAs($owner,'sanctum')->postJson("/api/v1/company/talents/{$candidate->id}/invite",['job_id'=>$job->id])->assertCreated()->json('data.id');$this->actingAs($candidate,'sanctum')->getJson('/api/v1/candidate/talent/invitations')->assertOk()->assertJsonCount(1,'data');$this->actingAs($candidate,'sanctum')->postJson("/api/v1/candidate/talent/invitations/{$invitation}/respond",['response'=>'accepted'])->assertOk();}public function test_hidden_candidate_is_not_searchable():void{$candidate=User::factory()->create(['account_type'=>'candidate']);$candidate->candidateProfile()->create(['professional_title'=>'Developer','talent_visibility'=>'hidden','available_for_opportunities'=>true]);$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active','verification_status'=>'verified']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$this->actingAs($owner,'sanctum')->getJson('/api/v1/company/talents')->assertOk()->assertJsonCount(0,'data.data');}}
